3220.docs:
Return all maximum elements of an iterator.

# Examples

```
use itertools::Itertools;

let a: [i32; 0] = [];
assert_eq!(a.iter().max_set(), Vec::<&i32>::new());

let a = [1];
assert_eq!(a.iter().max_set(), vec![&1]);

